        private static List<string> _lines = Utilities.StringToLines(Input);

        private static List<string> _grid = new();
        private static List<Coords> _barriers = new();
        private static HashSet<Coords> _visited = new();
        private static List<Coords> _barriersVisited = new(); // Store 5 last barriers to check loop

        public struct Coords
        {
            public int Row { get; set; }
            public int Col { get; set; }

            public Coords(int row, int col)
            {
                Row = row;
                Col = col;
            }
        }

        public enum Directions
        {
            Up,
            Right,
            Down,
            Left            
        }

        public record DirectionData(int RowDelta, int ColDelta, Func<Coords, Guard, bool> BarrierFilter, Func<IEnumerable<Coords>, IOrderedEnumerable<Coords>> BarrierOrder);

        private static readonly Dictionary<Directions, DirectionData> _directionMap = new()
        {
            [Directions.Up] = new DirectionData(RowDelta: -1, ColDelta: 0,
                BarrierFilter: (bar, guard) => bar.Col == guard.Coords.Col && bar.Row < guard.Coords.Row,
                BarrierOrder: bar => bar.OrderByDescending(b => b.Row)
            ),

            [Directions.Right] = new DirectionData(RowDelta: 0, ColDelta: +1,
                BarrierFilter: (b, g) => b.Row == g.Coords.Row && b.Col > g.Coords.Col,
                BarrierOrder: barriers => barriers.OrderBy(b => b.Col)
            ),

            [Directions.Down] = new DirectionData(RowDelta: +1, ColDelta: 0,
                BarrierFilter: (b, g) => b.Col == g.Coords.Col && b.Row > g.Coords.Row,
                BarrierOrder: barriers => barriers.OrderBy(b => b.Row)
            ),

            [Directions.Left] = new DirectionData(RowDelta: 0, ColDelta: -1,
                BarrierFilter: (b, g) => b.Row == g.Coords.Row && b.Col < g.Coords.Col,
                BarrierOrder: barriers => barriers.OrderByDescending(b => b.Col)
            )
        };

        public class Guard
        {
            public Directions Direction { get; set; }
            public Coords Coords { get; set; }

            public Guard(Coords coords)
            {
                Coords = coords;
                Direction = Directions.Up;
            }

            public void UpdateGuard(Coords stoppedCoords)
            {
                Coords = stoppedCoords;

                // Increment direction enum with wrapping
                var nextDirection = ((int)Direction + 1) % 4;
                Direction = (Directions)nextDirection;
            }
        }

        internal static long Part1()
        {
            foreach (var line in _lines)
            {
                _grid.Add(line);
            }

            for (int row = 0; row < _grid.Count; row++)
            {
                for (int col = 0; col < _grid[row].Length; col++)
                {
                    if (_grid[row][col] == '#')
                    {
                        _barriers.Add(new Coords(row, col));
                    }
                }
            }

            var guard = new Guard(GetGuardCoords());

            bool reachedEnd = false;
            while (!reachedEnd)
            {
                reachedEnd = IterateNext(guard);
            }

            return _visited.Count;
        }

        internal static long Part2()
        {
            int result = 0;
            foreach (var line in _lines)
            {
                _grid.Add(line);
            }

            for (int row = 0; row < _grid.Count; row++)
            {
                for (int col = 0; col < _grid[row].Length; col++)
                {
                    if (_grid[row][col] == '#')
                    {
                        _barriers.Add(new Coords(row, col));
                    }
                }
            }
            var guardCoords = GetGuardCoords();

            for (int row = 0; row < _grid.Count; row++)
            {
                for (int col = 0; col < _grid[row].Length; col++)
                {
                    if (_grid[row][col] == '.')
                    {
                        _barriersVisited.Clear();
                        var tempBarriers = new List<Coords>();
                        tempBarriers.AddRange(_barriers);
                        tempBarriers.Add(new Coords(row, col));

                        var guard = new Guard(guardCoords);
                        if (RunPart2(guard, tempBarriers))
                        {
                            Console.WriteLine($"Duplicate found at Row {row} - Col {col}");
                            result++;
                        }
                            
                    }
                }
            }

            return result;
        }

        internal static bool IterateNext(Guard g)
        {
            (Coords? guardPos, _, bool outOfMap) = GetNextPos(g, _barriers);
            AddVisited(start: g.Coords, end: guardPos, g.Direction);

            if (!outOfMap && guardPos is not null)
            {
                g.UpdateGuard(guardPos.Value);
                return false;
            }

            return true;
        }

        internal static bool RunPart2(Guard guard, List<Coords> tempBarriers)
        {
            bool reachedEnd = false;

            // Simulate whole path
            while (!reachedEnd)
            {
                reachedEnd = IterateNextPart2(guard, tempBarriers);

                // Check duplicates
                if (HasDuplicates(_barriersVisited))
                    return true;
            }
            return false;
        }

        internal static bool IterateNextPart2(Guard g, List<Coords> tempBarriers)
        {
            (Coords? guardPos, Coords? nextBarrier, bool outOfMap) = GetNextPos(g, tempBarriers);

            if (!outOfMap && guardPos is not null)
            {
                // Get barrier coords and add
                _barriersVisited.Add(nextBarrier.Value);
                g.UpdateGuard(guardPos.Value);
                return false;
            }

            return true;
        }

        private static (Coords? NextGuard, Coords? NextBarrier, bool OutOfMap) GetNextPos(Guard guard, List<Coords> barrierList)
        {
            var data = _directionMap[guard.Direction];

            var barriers = barrierList.Where(b => data.BarrierFilter(b, guard));
            var orderedBarriers = data.BarrierOrder(barriers);

            try
            {
                // Get next barrier in path
                var barrier = orderedBarriers.First();

                // Get the guard coords before barrier based on direction
                var newRow = barrier.Row - data.RowDelta;
                var newCol = barrier.Col - data.ColDelta;

                return (new Coords(newRow, newCol), barrier, false);
            }
            catch
            {
                // No barrier, out of map
                return (null, null, true);
            }
        }

        private static void AddVisited(Coords start, Coords? end, Directions direction)
        {
            var data = _directionMap[direction];

            var current = start;
            if (end is not null)
            {
                while (current.Row != end.Value.Row || current.Col != end.Value.Col)
                {
                    _visited.Add(current);
                    current = new Coords(current.Row + data.RowDelta, current.Col + data.ColDelta);
                }
            }
            else
            {
                while (IsInBounds(current.Row, current.Col))
                {
                    _visited.Add(current);
                    current = new Coords(current.Row + data.RowDelta, current.Col + data.ColDelta);
                }
            }
        }

        private static bool IsInBounds(int row, int col)
        {
            return row >= 0 && row < _grid.Count && col >= 0 && col < _grid[0].Count();
        }

        private static bool HasDuplicates(List<Coords> queue)
        {
            return queue
                .GroupBy(coords => coords)
                .Any(group => group.Count() > 4);
        }

        /// <summary>
        ///  Iterates each 'direction' change of guard, returns true if guard goes out of map
        /// </summary>
        internal static bool IterateNextStepOld(Guard g)
        {
            if (g.Direction == Directions.Up)
            {
                try
                {
                    var nextBarrier = _barriers
                    .Where(b => b.Col == g.Coords.Col && b.Row < g.Coords.Row)
                    .OrderByDescending(b => b.Row)
                    .First();

                    // Update visited
                    for (int row = g.Coords.Row; row > nextBarrier.Row; row--)
                    {
                        _visited.Add(new Coords(row, g.Coords.Col));
                    }

                    g.UpdateGuard(new Coords(nextBarrier.Row + 1, g.Coords.Col));
                    return false;
                }
                catch (Exception)
                {
                    // Update visited for edge
                    for (int row = g.Coords.Row; row >= 0; row--)
                    {
                        _visited.Add(new Coords(row, g.Coords.Col));
                    }

                    return true;
                }
            }
            else if (g.Direction == Directions.Right)
            {
                try
                {
                    var nextBarrier = _barriers
                    .Where(b => b.Col > g.Coords.Col && b.Row == g.Coords.Row)
                    .OrderBy(b => b.Col)
                    .First();

                    // Update visited
                    for (int col = g.Coords.Col; col < nextBarrier.Col; col++)
                    {
                        _visited.Add(new Coords(g.Coords.Row, col));
                    }

                    g.UpdateGuard(new Coords(g.Coords.Row, nextBarrier.Col - 1));
                    return false;
                }
                catch (Exception)
                {
                    // Update visited for edge
                    for (int col = g.Coords.Col; col < _grid[0].Count(); col++)
                    {
                        _visited.Add(new Coords(g.Coords.Row, col));
                    }

                    return true;
                }
            }
            else if (g.Direction == Directions.Down)
            {
                try
                {
                    var nextBarrier = _barriers
                    .Where(b => b.Col == g.Coords.Col && b.Row > g.Coords.Row)
                    .OrderBy(b => b.Row)
                    .First();

                    // Update visited
                    for (int row = g.Coords.Row; row < nextBarrier.Row; row++)
                    {
                        _visited.Add(new Coords(row, g.Coords.Col));
                    }

                    g.UpdateGuard(new Coords(nextBarrier.Row - 1, g.Coords.Col));
                    return false;
                }
                catch (Exception)
                {
                    // Update visited for edge
                    for (int row = g.Coords.Row; row < _grid.Count; row++)
                    {
                        _visited.Add(new Coords(row, g.Coords.Col));
                    }

                    return true;
                }
            }
            else if (g.Direction == Directions.Left)
            {
                try
                {
                    var nextBarrier = _barriers
                    .Where(b => b.Col < g.Coords.Col && b.Row == g.Coords.Row)
                    .OrderByDescending(b => b.Col)
                    .First();

                    // Update visited
                    for (int col = g.Coords.Col; col > nextBarrier.Col; col--)
                    {
                        _visited.Add(new Coords(g.Coords.Row, col));
                    }

                    g.UpdateGuard(new Coords(g.Coords.Row, nextBarrier.Col + 1));
                    return false;
                }
                catch (Exception)
                {
                    // Update visited for edge
                    for (int col = g.Coords.Col; col >= 0; col--)
                    {
                        _visited.Add(new Coords(g.Coords.Row, col));
                    }

                    return true;
                }
            }
            throw new InvalidOperationException();
        }

        internal static Coords GetGuardCoords()
        {
            for (int row = 0; row < _grid.Count; row++)
            {
                for (int col = 0; col < _grid[row].Length; col++)
                {
                    if (_grid[row][col] == '^')
                    {
                        return new Coords(row, col);
                    }
                }
            }
            return new Coords(0, 0);
        }
    }
